package com.narada.connection

import kotlinx.coroutines.runBlocking
import kotlinx.serialization.json.*
import org.junit.Assert.*
import org.junit.Test
import java.util.UUID

class TransfersClientTest {
    @Test fun manifestUsesBothHealthChecksAndVerifiesAllHashes()=runBlocking<Unit>{val f=TransferPeerFixture();assertEquals(f.bundle,f.prepare());assertEquals(2,f.healthCount);assertEquals(2,f.count)}
    @Test fun missingReadGrantBlocksPrepareBeforeAnyTransferControl()=runBlocking<Unit>{val f=TransferPeerFixture();f.health=f.health.copy(permissions=Permissions(roots=listOf(RootGrant(FileSamples.rootId,listOf("browse")))));expectFailure("ACCESS_DENIED"){runBlocking{f.prepare()}};assertEquals(0,f.count)}
    @Test fun readWithoutBrowseIsInsufficient()=runBlocking<Unit>{val f=TransferPeerFixture();f.health=f.health.copy(permissions=Permissions(roots=listOf(RootGrant(FileSamples.rootId,listOf("read")))));expectFailure("ACCESS_DENIED"){runBlocking{f.prepare()}};assertEquals(0,f.count)}
    @Test fun unadvertisedTransferProtocolHasNoFallback()=runBlocking<Unit>{val f=TransferPeerFixture();f.health=f.health.copy(operations=listOf("health","permissions","files.v1"));expectFailure("TRANSFERS_UNSUPPORTED"){runBlocking{f.prepare()}};assertEquals(0,f.count)}
    @Test fun hostileSourceRejectedBeforeHealth()=runBlocking<Unit>{val f=TransferPeerFixture();expectFailure{runBlocking{f.client.prepare(f.current(),f.session,f.record.copy(source=f.record.source.copy(object_id="content://private")))}};assertEquals(0,f.healthCount);assertEquals(0,f.count)}
    @Test fun replacementPairingCannotResumeOldTransfer()=runBlocking<Unit>{val f=TransferPeerFixture();f.memory.document=f.memory.document.replace(f.current().copy(attemptId=UUID.randomUUID().toString()));expectFailure("TRANSFER_SCOPE_CHANGED"){runBlocking{f.prepare()}};assertEquals(0,f.healthCount)}
    @Test fun localRevocationPreventsEveryChunkRequest()=runBlocking<Unit>{val f=TransferPeerFixture();f.pairing.revoke(f.record.peerId);expectFailure("TRANSFER_SCOPE_CHANGED"){runBlocking{f.chunk()}};assertEquals(0,f.chunkCount)}
    @Test fun postManifestGrantChangeDiscardsTheWholeBundle()=runBlocking<Unit>{val f=TransferPeerFixture();f.afterControl={if(it=="manifest")f.health=f.health.copy(grant_revision=2,permissions=Permissions())};expectFailure("TRANSFER_ACCESS_CHANGED"){runBlocking{f.prepare()}};assertEquals(2L,f.current().remoteRevision)}
    @Test fun correctChunkNeedsBothAuthenticationAndManifestHash()=runBlocking<Unit>{val f=TransferPeerFixture();val bytes=f.chunk();assertEquals(TransferRules.CHUNK,bytes.size);assertEquals(f.bundle.hashes[0],sha256(bytes));assertEquals(2,f.healthCount);bytes.fill(0)}
    @Test fun swappedOrDamagedChunkIsWipedAndNotPublished()=runBlocking<Unit>{val f=TransferPeerFixture();f.chunkTransform={it.apply{this[0]=(this[0].toInt() xor 1).toByte()}};expectFailure("HASH_MISMATCH"){runBlocking{f.chunk()}};assertTrue(f.returnedBytes!!.all{it==0.toByte()})}
    @Test fun postChunkRevocationWipesAlreadyDeliveredBytes()=runBlocking<Unit>{val f=TransferPeerFixture();f.afterChunk={f.health=f.health.copy(grant_revision=2,session_epoch=2,permissions=Permissions())};expectFailure("TRANSFER_ACCESS_CHANGED"){runBlocking{f.chunk()}};assertTrue(f.returnedBytes!!.all{it==0.toByte()})}
    @Test fun localEpochChangeAfterDataFencesTheReply()=runBlocking<Unit>{val f=TransferPeerFixture();f.afterChunk={f.memory.document=f.memory.document.replace(f.current().copy(localEpoch=f.current().localEpoch+1))};expectFailure("TRANSFER_SCOPE_CHANGED"){runBlocking{f.chunk()}};assertTrue(f.returnedBytes!!.all{it==0.toByte()})}
    @Test fun malformedManifestPaginationNeverAcceptsPartialDigestList()=runBlocking<Unit>{val f=TransferPeerFixture();f.transform={value->val obj=value.jsonObject;if(obj.containsKey("offset"))JsonObject(obj+mapOf("hashes" to JsonArray(emptyList())))else value};expectFailure("INVALID_MANIFEST"){runBlocking{f.prepare()}}}
    @Test fun remoteStorageFailureIsNotTheLocalIdentityLatch()=runBlocking<Unit>{val f=TransferPeerFixture();f.failCode="STORAGE_UNAVAILABLE";expectFailure("TRANSFER_REMOTE_STORAGE"){runBlocking{f.prepare()}};assertTrue(f.memory.document.enabled);assertFalse(f.current().blocked)}
    @Test fun unknownRemoteProseIsNotAStableErrorCode()=runBlocking<Unit>{val f=TransferPeerFixture();f.failCode="SECRET_SERVER_PATH";expectFailure("PEER_REJECTED"){runBlocking{f.prepare()}}}
    @Test fun foregroundGuardCanStopBeforeAnyNetworkTraffic()=runBlocking<Unit>{val f=TransferPeerFixture();expectFailure("FOREGROUND_PAUSED"){runBlocking{f.client.prepare(f.current(),f.session,f.record){fail("FOREGROUND_PAUSED")}}};assertEquals(0,f.healthCount)}
    @Test fun finishIsImpossibleWithoutPrivateReceipt()=runBlocking<Unit>{val f=TransferPeerFixture();expectFailure("TRANSFER_NOT_VERIFIED"){runBlocking{f.client.finish(f.current(),f.session,f.record)}};assertEquals(0,f.count)}
    @Test fun finishUsesSameIdAndRequiresValidatedAcknowledgment()=runBlocking<Unit>{val f=TransferPeerFixture();val m=f.bundle.manifest;val r=f.withManifest().copy(state=DownloadState.VERIFIED,runId=null,chunks=(0 until m.chunk_count).toList(),receipt=PrivateReceipt(m.manifest_id,m.sha256,m.bytes,System.currentTimeMillis()));f.memory.document=f.memory.document.replaceDownload(r);f.client.finish(f.current(),f.session,r);assertEquals(1,f.count);assertEquals(2,f.healthCount)}
    @Test fun missingProtectedIntentCannotInitiateRemotePreparation()=runBlocking<Unit>{val f=TransferPeerFixture();f.memory.document=f.memory.document.copy(downloads=emptyList());expectFailure("TRANSFER_INTENT_MISSING"){runBlocking{f.prepare()}};assertEquals(0,f.count);assertEquals(0,f.healthCount)}
    @Test fun callerCannotForgeAnUnsavedPrivateReceiptForFinish()=runBlocking<Unit>{val f=TransferPeerFixture();val m=f.bundle.manifest;val forged=f.withManifest().copy(state=DownloadState.VERIFIED,runId=null,chunks=(0 until m.chunk_count).toList(),receipt=PrivateReceipt(m.manifest_id,m.sha256,m.bytes,System.currentTimeMillis()));expectFailure("TRANSFER_STOPPED"){runBlocking{f.client.finish(f.current(),f.session,forged)}};assertEquals(0,f.count);assertEquals(0,f.healthCount)}
    @Test fun lateChunkCannotCrossAChangedDurableRunToken()=runBlocking<Unit>{val f=TransferPeerFixture();f.afterChunk={val r=f.memory.document.download(f.record.id);f.memory.document=f.memory.document.replaceDownload(r.copy(runId=UUID.randomUUID().toString()))};expectFailure("TRANSFER_STOPPED"){runBlocking{f.chunk()}};assertTrue(f.returnedBytes!!.all{it==0.toByte()})}
    @Test fun structurallyValidChangedSourceStillCannotBypassProtectedIntent()=runBlocking<Unit>{val f=TransferPeerFixture();expectFailure("TRANSFER_STOPPED"){runBlocking{f.client.prepare(f.current(),f.session,f.record.copy(source=f.record.source.copy(expected_version="c".repeat(64))))}};assertEquals(0,f.healthCount)}

}
